	@TestFactory
	public Stream<DynamicTest> blankNodeGraphNamesWorkForPositiveAndArbitraryBodies() {
		return List
				.of("<urn:blankSubject> <urn:blankPredicate> 'blank'",
						"VALUES ?marker { 1 } <urn:blankSubject> <urn:blankPredicate> 'blank'")
				.stream()
				// API-bound remote blank nodes are not supported by the pre-existing SPARQL transport.
				// The captured baseline capability matrix retains those two unsupported HTTP outcomes.
				.flatMap(body -> (isSPARQLServer() ? Stream.of(false) : Stream.of(false, true))
						.map(bound -> DynamicTest.dynamicTest("bound=" + bound + " / " + body, () -> {
							var blank = VF.createBNode("namedBlank");
							try (RepositoryConnection endpoint = getRepository(1).getConnection()) {
								endpoint.add(VF.createIRI("urn:blankSubject"), VF.createIRI("urn:blankPredicate"),
										literal("blank"), blank);
							}
							try (RepositoryConnection member = federationContext().getEndpointManager()
									.getEndpointByName("http://endpoint1")
									.getConnection();
									var result = member.prepareTupleQuery(
											"SELECT ?g WHERE { GRAPH ?g { <urn:blankSubject> <urn:blankPredicate> 'blank' } }")
											.evaluate()) {
								assertThat(QueryResults.asList(result)).extracting(row -> row.getValue("g"))
										.containsExactly(blank);
							}
							try (RepositoryConnection connection = fedxRule.getRepository().getConnection()) {
								TupleQuery query = connection
										.prepareTupleQuery("SELECT ?g WHERE { GRAPH ?g { " + body + " } }");
								if (bound) {
									query.setBinding("g", blank);
								}
								try (var rows = query.evaluate()) {
									assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("g"))
											.containsExactly(blank);
								}
							}
						})));
	}

